// 1. Pega os dados do NÓ ANTERIOR DIRETO (Netos: Resumos, Temas de Pesquisa e URLs)
const inputsDiretos = $input.all();

// 2. Pega os dados do NÓ "status diferente de ok1" (Pais e Filhos: Tópicos e Descrições)
let inputsConsolidados = [];
try {
  inputsConsolidados = $('status diferente de ok1').all();
} catch (error) {
  console.log("Nó 'status diferente de ok1' não retornou dados.");
}

if (inputsDiretos.length === 0 && inputsConsolidados.length === 0) {
  return [];
}

// 3. ID da Pesquisa
let idPesquisa = inputsDiretos[0]?.json?.id_pesquisa || inputsConsolidados[0]?.json?.id_pesquisa || null;

// 4. Tenta capturar o Relatório Primitivo Base
let relatorioPrimitivo = null;
try {
  const relatorioNodeData = $('verifica se é mesmo a fase relatar')?.first()?.json 
                         || $('verifica se é mesmo a fase redatar')?.first()?.json
                         || $('verifica se é mesmo a fase reatar')?.first()?.json;
  relatorioPrimitivo = relatorioNodeData?.relatorio || relatorioNodeData?.relatorio_final || null;
} catch (e) {
  // Ignora se não houver
}

// 5. CRIA A HIERARQUIA: PAI -> FILHO -> NETO
const estrutura = {};

function garantirHierarquia(passo) {
  const match = passo.match(/\d+/);
  const numeroTopico = match ? match[0] : "Outros";

  // Nível PAI (Tópico Principal)
  if (!estrutura[numeroTopico]) {
    estrutura[numeroTopico] = { 
      topico_id: numeroTopico, 
      topico_principal: "Tópico não nomeado", // Será preenchido pelo nó consolidado
      subtopicos: {} 
    };
  }

  // Nível FILHO (Subtópico)
  if (!estrutura[numeroTopico].subtopicos[passo]) {
    estrutura[numeroTopico].subtopicos[passo] = {
      passo_id: passo,
      descricao_subtopico: "", 
      consolidada: "",
      netos_pesquisas: [] // Array para guardar os Netos
    };
  }

  return {
    pai: estrutura[numeroTopico],
    filho: estrutura[numeroTopico].subtopicos[passo]
  };
}

// 5A. Preenche PAI e FILHO com dados do "status diferente de ok1"
// Como isso aqui apenas substitui variáveis (=""), não gera duplicidade
inputsConsolidados.forEach(item => {
  const json = item.json;
  if (!json.passo_id) return;

  const hierarquia = garantirHierarquia(json.passo_id);

  if (json.topico_principal) hierarquia.pai.topico_principal = json.topico_principal;
  if (json.descricao_subtopico) hierarquia.filho.descricao_subtopico = json.descricao_subtopico;
  if (json.informacao_consolidada) hierarquia.filho.consolidada = json.informacao_consolidada;
});

// 5B. Preenche os NETOS com dados do nó ANTERIOR DIRETO (COM TRAVA ANTIDUPLICIDADE)
inputsDiretos.forEach(item => {
  const json = item.json;
  if (!json.passo_id) return;

  const hierarquia = garantirHierarquia(json.passo_id);

  if (json.informacao_resumida || json.tema_pesquisa) {
    const novoResumo = json.informacao_resumida || "Sem resumo";
    const novoTema = json.tema_pesquisa || "Sem tema definido";
    const novaUrl = json.url_fonte || "URL não identificada";

    // ✅ A CORREÇÃO ESTÁ AQUI: Verifica se esse resumo exato já foi inserido neste subtópico
    const jaExiste = hierarquia.filho.netos_pesquisas.some(neto => neto.resumo === novoResumo);

    // Se não existir, aí sim ele adiciona. Se já existir, ele simplesmente descarta a cópia.
    if (!jaExiste) {
      hierarquia.filho.netos_pesquisas.push({
        tema_pesquisa: novoTema,
        resumo: novoResumo,
        url: novaUrl
      });
    }
  }
});


// 6. Monta o Prompt (Dossiê) visualmente alinhado com a hierarquia
let dossieTexto = `# INSTRUÇÃO PARA A IA REDATORA:\n`;
dossieTexto += `Sua missão é ATUALIZAR, REVISAR e EXPANDIR o **Relatório Primitivo Base** (se existente), incorporando de forma harmoniosa todas as novas evidências trazidas no **Dossiê de Pesquisa Profunda**.\n\n`;

dossieTexto += `========================================================\n`;
dossieTexto += `1. RELATÓRIO PRIMITIVO BASE (DOCUMENTO A SER ATUALIZADO)\n`;
dossieTexto += `========================================================\n`;
dossieTexto += `${relatorioPrimitivo ? relatorioPrimitivo : "(Nenhum relatório primitivo base encontrado. Gere o conteúdo do zero a partir do dossiê abaixo.)"}\n\n`;

dossieTexto += `========================================================\n`;
dossieTexto += `2. DOSSIÊ DE NOVAS DESCOBERTAS E EVIDÊNCIAS DE PESQUISA\n`;
dossieTexto += `========================================================\n`;
dossieTexto += `ID DA PESQUISA: ${idPesquisa || "N/A"}\n\n`;

const planoJson = [];
const topicosOrdenados = Object.keys(estrutura).sort((a, b) => parseInt(a) - parseInt(b));

// Renderiza a hierarquia no texto
topicosOrdenados.forEach(numTopico => {
  const pai = estrutura[numTopico];

  // Renderiza o PAI
  dossieTexto += `## 📁 PAI: ${pai.topico_principal}\n`;
  dossieTexto += `--------------------------------------------------------\n`;

  const subtopicosArray = [];
  const passosOrdenados = Object.keys(pai.subtopicos).sort((a, b) => a.localeCompare(b));

  passosOrdenados.forEach(passo => {
    const filho = pai.subtopicos[passo];

    // Renderiza o FILHO
    dossieTexto += `### 📄 FILHO [${filho.passo_id}]: ${filho.descricao_subtopico}\n\n`;

    if (filho.consolidada) {
      dossieTexto += `**Conclusão/Síntese do Auditor para este subtópico:**\n${filho.consolidada}\n\n`;
    }

    // Renderiza os NETOS
    if (filho.netos_pesquisas.length > 0) {
      dossieTexto += `**🔬 NETOS (Pesquisas Individuais Realizadas):**\n`;
      filho.netos_pesquisas.forEach((neto, index) => {
        dossieTexto += `\n> **Pesquisa ${index + 1} | Tema:** ${neto.tema_pesquisa}\n`;
        dossieTexto += `> **Fonte:** ${neto.url}\n`;
        dossieTexto += `> **Resumo:** ${neto.resumo}\n`;
      });
      dossieTexto += `\n`;
    }

    dossieTexto += `--------------------------------------------------------\n`;

    // Monta a estrutura de dados limpa (JSON)
    subtopicosArray.push({
      passo: filho.passo_id,
      descricao_subtopico: filho.descricao_subtopico,
      conclusao_auditor: filho.consolidada,
      pesquisas_realizadas: filho.netos_pesquisas // Aqui estão os netos limpos e sem duplicatas!
    });
  });

  planoJson.push({
    topico_principal: pai.topico_principal,
    subtopicos: subtopicosArray
  });

  dossieTexto += `\n`;
});

// 7. Retorna 1 ÚNICO item empacotado para o LLM Redator
return [{
  json: {
    id_pesquisa: idPesquisa,
    relatorio_primitivo_base: relatorioPrimitivo, 
    plano_json_estruturado: planoJson, 
    dossie_pronto_para_ia: dossieTexto 
  }
}];

